CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('admin', 'customer');
CREATE TYPE project_status AS ENUM ('planning', 'design', 'development', 'testing', 'launch', 'maintenance', 'completed');
CREATE TYPE invoice_status AS ENUM ('draft', 'open', 'paid', 'overdue', 'cancelled');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email varchar(254) NOT NULL UNIQUE, password_hash text NOT NULL, role user_role NOT NULL DEFAULT 'customer', name varchar(120) NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, secret_hash varchar(128) NOT NULL UNIQUE, expires_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE password_reset_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash varchar(128) NOT NULL UNIQUE, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE email_verification_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash varchar(128) NOT NULL UNIQUE, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company varchar(120) NOT NULL, name varchar(120) NOT NULL, email varchar(254) NOT NULL, phone varchar(40), project_type varchar(64) NOT NULL, budget varchar(32), message text NOT NULL, privacy_accepted_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES users(id), title varchar(180) NOT NULL, description text, status project_status NOT NULL DEFAULT 'planning', progress integer NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100), next_step varchar(500), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES users(id), invoice_number varchar(64) NOT NULL UNIQUE, issue_date timestamptz NOT NULL, due_date timestamptz NOT NULL, currency varchar(3) NOT NULL DEFAULT 'EUR', net_amount numeric(12,2) NOT NULL, tax_amount numeric(12,2) NOT NULL, gross_amount numeric(12,2) NOT NULL, status invoice_status NOT NULL DEFAULT 'draft', pdf_storage_key varchar(255), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES users(id), project_id uuid REFERENCES projects(id), storage_key varchar(255) NOT NULL UNIQUE, display_name varchar(255) NOT NULL, media_type varchar(120) NOT NULL, size_bytes integer NOT NULL CHECK (size_bytes >= 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), action varchar(80) NOT NULL, entity_type varchar(80), entity_id uuid, request_id uuid, metadata text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_id_idx ON sessions(user_id); CREATE INDEX inquiries_created_at_idx ON inquiries(created_at DESC); CREATE INDEX projects_customer_id_idx ON projects(customer_id); CREATE INDEX invoices_customer_id_idx ON invoices(customer_id); CREATE INDEX documents_customer_id_idx ON documents(customer_id); CREATE INDEX audit_logs_user_id_created_at_idx ON audit_logs(user_id, created_at DESC);
